import { RingBuffer } from "../shared/rt/ringBuffer";
import { resolveWorkletSampleRate } from "../utils/workletSampleRate";
import { getStretchProfileOptions } from "../engines/rubberband/stretchProfiles";
// @ts-ignore - The file is generated by the build script
import createRubberBandModule from "./rubberband-lib.js";

// --- LCG (Linear Congruential Generator) Constants ---
// Standard parameters for GC-free pseudo-random number generation
const LCG_MULTIPLIER = 1103515245;
const LCG_INCREMENT = 12345;
const LCG_MODULUS = 0x7FFFFFFF;

class SustainProcessor extends AudioWorkletProcessor {
    private buffer: Float32Array | null = null;
    private readonly sampleRate: number;

    private readonly readyMessage = { type: 'READY' as const };
    private readonly errorMessage = { type: 'ERROR' as const, error: '' };

    // Playback State
    private playhead = 0;
    private isPlaying = false;
    private basePitch = 1.0; // The pitch of the sample

    // Arpeggiator State
    private arpCounter = 0;     // Counts samples
    private arpStepIndex = 0;   // Which step of the pattern are we on?
    private arpPattern: number[] = [0, 4, 7, 12]; // Default: Major Triad + Octave (semitones)

    // Parameters
    private loopStart = 0;
    private loopEnd = 0;
    private grainSize = 4410; // Default grain size (~100ms at 44.1kHz)
    private grainOverlap = 0.5; // Overlap factor for smoother stretching

    // Wavetable
    private baseFrequency = 220; // Base Hz before pitch offsets

    // Stretch mode state (for crossfade grains)
    private grainPhase = 0;

    // Pre-computed zero-crossing positions (optional optimization)
    private zeroCrossings: Int32Array | null = null;

    // Rubber Band Integration
    private rubberBand: any = null;
    private inputRingBuffer: RingBuffer | null = null;
    private outputRingBuffer: RingBuffer | null = null;
    private inputHeapPtr: number = 0;
    private outputHeapPtr: number = 0;
    private heapSizeFrames: number = 0;
    private rubberBandInitialized = false;
    private useRubberBand = false; // Enable/disable Rubber Band mode

    constructor() {
        super();
        this.sampleRate = resolveWorkletSampleRate();

        // Message handler for receiving buffer and settings
        this.port.onmessage = async (event: MessageEvent) => {
            const { type, data } = event.data;

            switch (type) {
                case 'INIT_WASM':
                    try {
                        // Initialize Rubber Band WASM module
                        const { inputBuffer, outputBuffer, wasmBinary } = event.data;
                        
                        this.inputRingBuffer = new RingBuffer(inputBuffer);
                        this.outputRingBuffer = new RingBuffer(outputBuffer);

                        if (!wasmBinary) {
                            throw new Error("WASM binary not provided in INIT_WASM message");
                        }

                        // @ts-ignore
                        const module = await createRubberBandModule({
                            wasmBinary: wasmBinary,
                            locateFile: (path: string) => {
                                if (path.endsWith('.wasm')) return import.meta.env.BASE_URL + 'rubberband.wasm';
                                return path;
                            }
                        });

                        const safeSampleRate = Math.floor(this.sampleRate);

                        const options = getStretchProfileOptions('vocal');

                        this.rubberBand = new module.RubberBandStretcher(
                            safeSampleRate,
                            1, // Mono
                            options,
                            1.0, // Initial Time Ratio
                            1.0  // Initial Pitch Scale
                        );

                        this.rubberBand.module = module;
                        this.rubberBandInitialized = true;
                        this.port.postMessage(this.readyMessage);
                    } catch (e) {
                        console.error("RubberBand WASM Failed:", e);
                        this.errorMessage.error = String(e);
                        this.port.postMessage(this.errorMessage);
                    }
                    break;

                case 'loadBuffer':
                    this.buffer = new Float32Array(data.buffer);
                    this.loopEnd = this.buffer.length;
                    this.loopStart = 0;
                    this.playhead = 0;
                    // Pre-compute zero crossings for this buffer
                    this.zeroCrossings = this.findZeroCrossings(this.buffer);
                    break;

                case 'setLoopPoints':
                    this.loopStart = data.start || 0;
                    this.loopEnd = data.end || (this.buffer ? this.buffer.length : 0);
                    break;

                case 'setArpPattern':
                    this.arpPattern = data.pattern || [0, 4, 7, 12];
                    this.arpStepIndex = 0;
                    break;

                case 'noteOn':
                    this.isPlaying = true;
                    this.playhead = this.loopStart;
                    this.basePitch = data.pitch || 1.0;
                    this.grainPhase = 0;
                    
                    // If Rubber Band is initialized and enabled, feed the buffer to it
                    if (this.useRubberBand && this.rubberBandInitialized && this.rubberBand && this.buffer) {
                        this.rubberBand.reset();
                        this.rubberBand.setPitchScale(data.pitch || 1.0);
                        this.rubberBand.setTimeRatio(1.0);

                        // Support for slicing
                        const startSample = Math.max(0, Math.floor(this.loopStart));
                        const endSample = Math.min(this.buffer.length, Math.floor(this.loopEnd));
                        
                        if (startSample < endSample) {
                            const sliceLength = endSample - startSample;
                            this.ensureHeapSize(sliceLength);

                            const heap = this.rubberBand.module.HEAPF32;
                            const ptr = this.inputHeapPtr >> 2;
                            for (let i = 0; i < sliceLength; i++) {
                                heap[ptr + i] = this.buffer[startSample + i];
                            }
                            this.rubberBand.process(this.inputHeapPtr, sliceLength, false);
                        }
                    }
                    break;

                case 'noteOff':
                    this.isPlaying = false;
                    break;

                case 'setGrainSize':
                    this.grainSize = data.size || 4410;
                    break;

                case 'enableRubberBand':
                    this.useRubberBand = data.enabled || false;
                    break;
            }
        };
    }

    static get parameterDescriptors() {
        return [
            { name: 'mode', defaultValue: 0, minValue: 0, maxValue: 3 }, // 0=LOOP, 1=STRETCH, 2=WAVETABLE, 3=RUBBERBAND
            { name: 'bpm', defaultValue: 120, minValue: 20, maxValue: 300 },
            { name: 'arp', defaultValue: 0, minValue: 0, maxValue: 1 }, // 0 = Off, 1 = On
            { name: 'pitch', defaultValue: 1.0, minValue: 0.25, maxValue: 4.0 },
            { name: 'frequency', defaultValue: 220, minValue: 20, maxValue: 20000 }
        ];
    }

    /**
     * Find zero-crossing positions in the buffer for clean loop points.
     * Uses a simple positive-going zero-crossing detection.
     */
    private findZeroCrossings(buffer: Float32Array): Int32Array {
        // Pre-allocate array (estimate ~sampleRate/100 crossings per second for typical audio)
        const crossings: number[] = [];
        for (let i = 1; i < buffer.length; i++) {
            if (buffer[i] >= 0 && buffer[i - 1] < 0) {
                crossings.push(i);
            }
        }
        return new Int32Array(crossings);
    }

    /**
     * Find the nearest zero-crossing to a given position.
     * Uses binary search for efficiency.
     */
    private findNearestZeroCrossing(position: number): number {
        if (!this.zeroCrossings || this.zeroCrossings.length === 0) {
            return Math.floor(position);
        }

        // Binary search for nearest zero crossing
        let low = 0;
        let high = this.zeroCrossings.length - 1;

        while (low < high) {
            const mid = (low + high) >>> 1;
            if (this.zeroCrossings[mid] < position) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }

        // Check which of the two closest is nearer
        if (low > 0) {
            const prev = this.zeroCrossings[low - 1];
            const curr = this.zeroCrossings[low];
            if (Math.abs(position - prev) < Math.abs(position - curr)) {
                return prev;
            }
        }

        return this.zeroCrossings[low] || Math.floor(position);
    }

    /**
     * Linear Interpolation for high-quality pitch/stretch.
     * Prevents aliasing at non-integer playback rates.
     */
    private getInterpolatedSample(position: number): number {
        if (!this.buffer || this.buffer.length === 0) return 0;

        const indexA = Math.floor(position);
        const indexB = indexA + 1;
        const fraction = position - indexA;

        // Safety check
        if (indexA < 0 || indexA >= this.buffer.length) return 0;

        const valA = this.buffer[indexA];
        const valB = (indexB < this.buffer.length) ? this.buffer[indexB] : 0;

        return valA + (valB - valA) * fraction;
    }

    /**
     * Generate a random position within the grain window for stretch mode.
     * Uses a simple LCG for GC-free random numbers.
     */
    private getStretchJumpPosition(): number {
        // LCG for deterministic randomness without GC
        this.grainPhase = (this.grainPhase * LCG_MULTIPLIER + LCG_INCREMENT) & LCG_MODULUS;
        const randomFactor = (this.grainPhase / LCG_MODULUS);

        // Jump to a position within the grain window
        const windowSize = this.grainSize * this.grainOverlap;
        return this.loopStart + (randomFactor * windowSize);
    }

    /**
     * Ensure WASM heap has enough space allocated for Rubber Band processing.
     */
    private ensureHeapSize(frames: number) {
        if (!this.rubberBand) return;
        
        if (frames > this.heapSizeFrames) {
            if (this.inputHeapPtr) this.rubberBand.module._free(this.inputHeapPtr);
            if (this.outputHeapPtr) this.rubberBand.module._free(this.outputHeapPtr);

            this.inputHeapPtr = this.rubberBand.module._malloc(frames * 4);
            this.outputHeapPtr = this.rubberBand.module._malloc(frames * 4);
            this.heapSizeFrames = frames;
        }
    }

    process(_inputs: Float32Array[][], outputs: Float32Array[][], parameters: Record<string, Float32Array>): boolean {
        const output = outputs[0];
        if (!output || output.length === 0) return true;

        const bpmParam = parameters['bpm'];
        const arpParam = parameters['arp'];
        const modeParam = parameters['mode'];
        const pitchParam = parameters['pitch'];
        const freqParam = parameters['frequency'];

        const arpConstant = arpParam.length === 1;
        // modeParam length check not needed - we read mode directly below
        const pitchConstant = pitchParam.length === 1;
        const freqConstant = freqParam.length === 1;
        const bpmConstant = bpmParam.length === 1;

        const blockSize = output[0].length;
        // Use global sampleRate or fallback
        const currentSampleRate = this.sampleRate;
        
        // Get mode once for the entire block
        const mode = modeParam[0];
        
        // --- MODE D: RUBBERBAND (high-quality pitch shifting) ---
        // Mode 3 (value >= 2.5 to handle float parameter values between modes)
        if (mode >= 2.5 && this.rubberBandInitialized && this.rubberBand && this.inputRingBuffer && this.outputRingBuffer) {
            const outputChannel = output[0];
            const currentPitch = pitchParam[0];
            
            this.rubberBand.setPitchScale(currentPitch);
            this.rubberBand.setTimeRatio(1.0);

            try {
                const required = this.rubberBand.getSamplesRequired();
                const available = this.inputRingBuffer.availableRead();

                if (available >= required && required > 0) {
                    this.ensureHeapSize(required);
                    this.inputRingBuffer.pull(this.rubberBand.module.HEAPF32, this.inputHeapPtr >> 2);
                    this.rubberBand.process(this.inputHeapPtr, required, false);
                }

                const availOutput = this.rubberBand.available();
                if (availOutput > 0) {
                    const framesToRead = Math.min(availOutput, 128);
                    this.ensureHeapSize(framesToRead);
                    
                    const retrieved = this.rubberBand.retrieve(this.outputHeapPtr, framesToRead);

                    const heap = this.rubberBand.module.HEAPF32;
                    const ptr = this.outputHeapPtr >> 2;
                    const limit = Math.min(retrieved, blockSize);
                    for(let i=0; i<limit; i++) {
                        outputChannel[i] = heap[ptr + i];
                    }
                    
                    // Copy to all channels
                    for (let channel = 1; channel < output.length; channel++) {
                        output[channel].set(outputChannel);
                    }
                }
            } catch (e) {
                console.error("Rubber Band DSP Error:", e);
            }

            return true;
        }

        // --- ORIGINAL MODES (LOOP, STRETCH, WAVETABLE) ---
        const buffer = this.buffer;
        const bufLen = buffer ? buffer.length : 0;
        const loopStart = this.loopStart;
        const loopEnd = this.loopEnd;
        const grainSize = this.grainSize;
        const baseFrequency = this.baseFrequency;

        let playhead = this.playhead;
        let arpCounter = this.arpCounter;
        let arpStepIndex = this.arpStepIndex;
        let basePitch = this.basePitch;
        let isPlaying = this.isPlaying;

        const outL = output[0];

        if (!buffer) {
            outL.fill(0);
        } else if (mode < 0.5) { // MODE A: LOOP
            const arpPattern = this.arpPattern;
            const arpPatternLength = arpPattern.length;
            const ln2_12 = Math.LN2 / 12.0;
            const currentBpm0 = bpmParam[0];
            const currentPitch0 = pitchParam[0];
            const arpParam0 = arpParam[0];

            for (let i = 0; i < blockSize; i++) {
                const arpOn = (arpConstant ? arpParam0 : arpParam[i]) > 0.5;

                if (arpOn) {
                    const currentBpm = bpmConstant ? currentBpm0 : bpmParam[i];
                    const samplesPerStep = (currentSampleRate * 60) / (currentBpm * 4);
                    arpCounter++;
                    if (arpCounter >= samplesPerStep) {
                        arpCounter = 0;
                        const semiTone = arpPattern[arpStepIndex % arpPatternLength];
                        basePitch = Math.exp(semiTone * ln2_12);
                        playhead = loopStart;
                        this.isPlaying = true; // Update state directly
                        isPlaying = true;
                        arpStepIndex++;
                    }
                }

                if (!isPlaying) {
                    outL[i] = 0;
                    continue;
                }

                const indexA = playhead | 0;
                let sampleValue = 0;
                if (indexA >= 0 && indexA < bufLen) {
                    const valA = buffer[indexA];
                    const indexB = indexA + 1;
                    const valB = indexB < bufLen ? buffer[indexB] : 0;
                    sampleValue = valA + (valB - valA) * (playhead - indexA);
                }
                outL[i] = sampleValue;

                const currentPitch = pitchConstant ? currentPitch0 : pitchParam[i];
                playhead += arpOn ? basePitch : (currentPitch || 1.0);
                if (playhead >= loopEnd) {
                    playhead = this.findNearestZeroCrossing(loopStart);
                }
            }
        } else if (mode < 1.5) { // MODE B: STRETCH
            const arpPattern = this.arpPattern;
            const arpPatternLength = arpPattern.length;
            const ln2_12 = Math.LN2 / 12.0;
            const currentBpm0 = bpmParam[0];
            const currentPitch0 = pitchParam[0];
            const arpParam0 = arpParam[0];

            for (let i = 0; i < blockSize; i++) {
                const arpOn = (arpConstant ? arpParam0 : arpParam[i]) > 0.5;

                if (arpOn) {
                    const currentBpm = bpmConstant ? currentBpm0 : bpmParam[i];
                    const samplesPerStep = (currentSampleRate * 60) / (currentBpm * 4);
                    arpCounter++;
                    if (arpCounter >= samplesPerStep) {
                        arpCounter = 0;
                        const semiTone = arpPattern[arpStepIndex % arpPatternLength];
                        basePitch = Math.exp(semiTone * ln2_12);
                        playhead = loopStart;
                        this.isPlaying = true;
                        isPlaying = true;
                        arpStepIndex++;
                    }
                }

                if (!isPlaying) {
                    outL[i] = 0;
                    continue;
                }

                const indexA = playhead | 0;
                let sampleValue = 0;
                if (indexA >= 0 && indexA < bufLen) {
                    const valA = buffer[indexA];
                    const indexB = indexA + 1;
                    const valB = indexB < bufLen ? buffer[indexB] : 0;
                    sampleValue = valA + (valB - valA) * (playhead - indexA);
                }
                outL[i] = sampleValue;

                const currentPitch = pitchConstant ? currentPitch0 : pitchParam[i];
                playhead += arpOn ? basePitch : (currentPitch || 1.0);
                if (playhead >= (loopStart + grainSize)) {
                    playhead = this.getStretchJumpPosition();
                }
            }
        } else { // MODE C: WAVETABLE
            const arpPattern = this.arpPattern;
            const arpPatternLength = arpPattern.length;
            const ln2_12 = Math.LN2 / 12.0;
            const currentBpm0 = bpmParam[0];
            const currentPitch0 = pitchParam[0];
            const currentFreq0 = freqParam[0];
            const arpParam0 = arpParam[0];
            const srInv = 1.0 / currentSampleRate;

            for (let i = 0; i < blockSize; i++) {
                const arpOn = (arpConstant ? arpParam0 : arpParam[i]) > 0.5;

                if (arpOn) {
                    const currentBpm = bpmConstant ? currentBpm0 : bpmParam[i];
                    const samplesPerStep = (currentSampleRate * 60) / (currentBpm * 4);
                    arpCounter++;
                    if (arpCounter >= samplesPerStep) {
                        arpCounter = 0;
                        const semiTone = arpPattern[arpStepIndex % arpPatternLength];
                        basePitch = Math.exp(semiTone * ln2_12);
                        playhead = loopStart;
                        this.isPlaying = true;
                        isPlaying = true;
                        arpStepIndex++;
                    }
                }

                if (!isPlaying) {
                    outL[i] = 0;
                    continue;
                }

                let phase = playhead;
                while (phase >= bufLen) phase -= bufLen;

                const indexA = phase | 0;
                let sampleValue = 0;
                if (indexA >= 0 && indexA < bufLen) {
                    const valA = buffer[indexA];
                    const indexB = indexA + 1;
                    const valB = indexB < bufLen ? buffer[indexB] : 0;
                    sampleValue = valA + (valB - valA) * (phase - indexA);
                }
                outL[i] = sampleValue;

                const currentPitch = pitchConstant ? currentPitch0 : pitchParam[i];
                const currentFreq = freqConstant ? currentFreq0 : freqParam[i];
                const pitchRatio = arpOn ? basePitch : (currentPitch || 1.0);
                const targetFreq = (currentFreq || baseFrequency) * pitchRatio;
                playhead += (targetFreq * bufLen) * srInv;
                if (playhead >= bufLen) {
                    playhead -= bufLen;
                }
            }
        }

        this.playhead = playhead;
        this.arpCounter = arpCounter;
        this.arpStepIndex = arpStepIndex;
        this.basePitch = basePitch;
        this.isPlaying = isPlaying;

        // Copy to all channels
        for (let channel = 1; channel < output.length; channel++) {
            output[channel].set(output[0]);
        }

        return true;
    }
}

registerProcessor('sustain-processor', SustainProcessor);
